        let node;
        let nodeNormals;
        for (let i = 0; i < nbVertices; i++) {
          node = bodyVertices.at(i);
          nodeNormals = node.get_m_n();
          nodeNormals.setX(triNorms[3 * i]);
          nodeNormals.setY(triNorms[3 * i + 1]);
          nodeNormals.setZ(triNorms[3 * i + 2]);
        }
